require "vendor/autoload.php";
$dirs = ["packages/core/src/Exceptions", "packages/drive/src/Exceptions", "packages/documents/src/Exceptions"];
$classes = [];
$it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator("packages"));
foreach ($it as $f) {
    if (!$f->isFile() || !str_ends_with($f->getPathname(), ".php")) continue;
    $p = $f->getPathname();
    if (!preg_match("#packages/(core|drive|documents)/src/Exceptions/#", $p)) continue;
    $src = file_get_contents($p);
    if (!preg_match("/namespace ([^;]+);/", $src, $ns)) continue;
    if (!preg_match("/(?:class|interface|trait|enum) ([A-Za-z0-9_]+)/", $src, $cn)) continue;
    $fqcn = $ns[1]."\\\\".$cn[1];
    if (!class_exists($fqcn)) { echo "LOAD FAIL $fqcn\n"; continue; }
    if (!is_subclass_of($fqcn, Vaulter\Exceptions\Contracts\ProblemException::class) && $fqcn !== Vaulter\Exceptions\Contracts\ProblemException::class) continue;
    $ref = new ReflectionClass($fqcn);
    if ($ref->isAbstract() || $ref->isInterface()) continue;
    $hasDetails = $ref->hasMethod("problemDetails");
    $decl = $hasDetails ? $ref->getMethod("problemDetails")->getDeclaringClass()->getName() : "MISSING";
    $classes[] = $fqcn;
    echo $fqcn." details=".$decl."\n";
}
echo "COUNT ".count($classes)."\n";
